<?php
require_once '../config/db.php'; require_once 'includes/header.php'; require_once 'includes/sidebar.php';
$metrics=['balance'=>(float)$pdo->query('SELECT COALESCE(SUM(current_balance),0) FROM accounts WHERE is_active=1')->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(amount_paid),0) FROM invoices WHERE status<>'voided'")->fetchColumn(),'expenses'=>(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM expenses')->fetchColumn(),'receivable'=>(float)$pdo->query("SELECT COALESCE(SUM(grand_total-amount_paid),0) FROM invoices WHERE status IN ('sent','unpaid','partial')")->fetchColumn(),'payable'=>(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM debits WHERE status='pending'")->fetchColumn()];
$recent=$pdo->query("SELECT i.id,i.invoice_number,i.issue_date,i.grand_total,i.status,c.company_name FROM invoices i JOIN contacts c ON c.id=i.contact_id ORDER BY i.created_at DESC LIMIT 7")->fetchAll();
$monthly=$pdo->query("SELECT DATE_FORMAT(issue_date,'%Y-%m') month,COALESCE(SUM(amount_paid),0) amount FROM invoices WHERE issue_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY month ORDER BY month")->fetchAll();$maxMonth=max(array_column($monthly,'amount')?:[1]);
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex items-center justify-between sticky top-0 z-10"><div class="flex items-center gap-4"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Financial overview</h2><p class="text-sm text-slate-500"><?=h(date('l, F j, Y'))?></p></div></div><a href="invoice/create_invoice.php" class="brand-bg text-white px-4 py-2.5 rounded-lg font-semibold text-sm">+ New invoice</a></header>
