<?php foreach($recent as $inv):?><tr class="hover:bg-slate-50"><td class="px-5 py-4"><a class="font-bold brand-text" href="invoice/view_invoice.php?id=<?=$inv['id']?>"><?=h($inv['invoice_number'])?></a><p class="text-xs text-slate-400"><?=h(date('M j',strtotime($inv['issue_date'])))?></p></td><td class="px-5 py-4"><?=h($inv['company_name'])?></td><td class="px-5 py-4 text-right money font-semibold"><?=money($pdo,$inv['grand_total'])?></td><td class="px-5 py-4"><span class="px-2.5 py-1 rounded-full text-xs font-bold bg-slate-100"><?=h(ucfirst($inv['status']))?></span></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="4" class="p-10 text-center text-slate-500">No invoices yet. Create your first invoice to start tracking revenue.</td></tr><?php endif;?></tbody></table></div></section>
<aside class="space-y-7"><section class="bg-slate-950 text-white rounded-2xl p-6 shadow-sm"><p class="text-sm text-slate-400">Net operating position</p><p class="text-3xl font-black mt-2"><?=money($pdo,$metrics['revenue']-$metrics['expenses'])?></p><p class="text-sm text-slate-400 mt-2">Collected revenue minus operating expenses</p><a href="report_genaretor.php" class="inline-block mt-5 text-sm font-bold brand-text">Open reports →</a></section><section class="bg-white border rounded-2xl p-6 shadow-sm"><h3 class="font-bold">Revenue trend</h3><div class="h-40 flex items-end gap-3 mt-5"><?php foreach($monthly as $m):$height=max(8,($m['amount']/$maxMonth)*100);?><div class="flex-1 text-center"><div class="brand-bg rounded-t-md mx-auto" style="height:<?=$height?>px"></div><span class="text-[10px] text-slate-400"><?=h(date('M',strtotime($m['month'].'-01')))?></span></div><?php endforeach;?><?php if(!$monthly):?><p class="text-sm text-slate-400 self-center">Chart will appear after payments are recorded.</p><?php endif;?></div></section></aside></div></div></main>
